-- c001-v004: ခိုးဝင်ခဲ့ကြ အကြောင်းမူကား အချို့ လူများ –ထိုသူတို့ ရှေးကပင် ရေးသားသတ်မှတ်ထားသော –သို့ ဤသည် –ထို တရားစီရင်ခြင်း မကိုင်းမရိုင်းသောသူများ –ထိုသည်ကို –၏ ဘုရားသခင်၏ ကျွန်ုပ်တို့၏ ကျေးဇူးတော် ပြောင်းလဲလျက် –သို့ ကာမဂုဏ်လွန်ကျူးခြင်း နှင့် –ထို တစ်ဦးတည်းသော အရှင်သခင် နှင့် သခင်ဘုရား ကျွန်ုပ်တို့၏ ယေရှု ခရစ်တော်ကို ငြင်းပယ်လျက်
